begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(17);
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data) values
('f1400000-0000-4000-8000-000000000001','platform@example.test',now(),'{"platform_role":"system_admin"}'),
('f1400000-0000-4000-8000-000000000002','manager@example.test',now(),'{}'),
('f1400000-0000-4000-8000-000000000003','other@example.test',now(),'{}');
update membership_private.password_setup set completed=true where user_id='f1400000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1400000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.company',public.platform_create('{"requestId":"f1400000-0000-4000-8000-000000000010","name":"Invitation test","slug":"invitation-test","accountEmail":"manager@example.test"}')::text,true);
select set_config('test.invite',(current_setting('test.company')::jsonb->'invitation'->>'id'),true);
select set_config('request.jwt.claims','{"sub":"f1400000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.platform_accept_manager_invitation(current_setting('test.invite')::uuid)$$,'P0001','PASSWORD_SETUP_REQUIRED','password setup is required before acceptance');
reset role;
update membership_private.password_setup set completed=true where user_id='f1400000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($$select public.platform_accept_manager_invitation(current_setting('test.invite')::uuid)$$,'P0001','PERMISSION_DENIED','wrong recipient is denied');
select set_config('request.jwt.claims','{"sub":"f1400000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(jsonb_array_length(public.platform_my_manager_invitations()->'items'),1,'recipient sees own invitation');
select lives_ok($$select public.platform_accept_manager_invitation(current_setting('test.invite')::uuid)$$,'recipient accepts invitation');
select lives_ok($$select public.platform_accept_manager_invitation(current_setting('test.invite')::uuid)$$,'accept is idempotent');
reset role;
select is((select role::text from public.workspace_members where workspace_id=(current_setting('test.company')::jsonb->>'id')::uuid and user_id='f1400000-0000-4000-8000-000000000002'),'admin','recipient becomes Marketing Manager');
select is((select count(*)::int from public.workspace_team_members where workspace_id=(current_setting('test.company')::jsonb->>'id')::uuid),1,'one default-team assignment');
select is((select count(*)::int from platform_private.audit_events where workspace_id=(current_setting('test.company')::jsonb->>'id')::uuid and action='manager_invitation_accepted' and actor_id='f1400000-0000-4000-8000-000000000002'),1,'accept audit has correct actor once');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1400000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.platform_invitation_action(current_setting('test.invite')::uuid,'claim')$$,'P0001','INVITATION_REVOKED','accepted invitation cannot send again');
select set_config('test.expired',(public.platform_create('{"requestId":"f1400000-0000-4000-8000-000000000011","name":"Expired invitation","slug":"expired-manager-invitation","accountEmail":"manager@example.test"}')->'invitation'->>'id'),true);
reset role;
update platform_private.manager_invitations set expires_at=now()-interval '1 second' where id=current_setting('test.expired')::uuid;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1400000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.platform_accept_manager_invitation(current_setting('test.expired')::uuid)$$,'P0001','INVITATION_EXPIRED','expired manager invitation grants nothing');
select set_config('request.jwt.claims','{"sub":"f1400000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.platform_invitation_action(current_setting('test.expired')::uuid,'revoke')$$,'platform revokes pending manager invitation');
select set_config('request.jwt.claims','{"sub":"f1400000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.platform_accept_manager_invitation(current_setting('test.expired')::uuid)$$,'P0001','INVITATION_REVOKED','revoked manager invitation grants nothing');
select ok(not has_function_privilege('authenticated','public.platform_record_delivery(uuid,uuid,boolean)','EXECUTE'),'browser cannot forge delivery success');
reset role;
select set_config('test.expired_ws',(select workspace_id::text from platform_private.manager_invitations where id=current_setting('test.expired')::uuid),true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1400000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.platform_issue_manager_invitation(current_setting('test.expired_ws')::uuid,'manager@example.test')$$,'revoked invitation can be replaced explicitly');
select lives_ok($$select public.platform_issue_manager_invitation(current_setting('test.expired_ws')::uuid,'manager@example.test')$$,'reissue retry is idempotent');
reset role;
select set_config('test.reissued',(select id::text from platform_private.manager_invitations where workspace_id=current_setting('test.expired_ws')::uuid and status='pending'),true);
update auth.users set raw_app_meta_data='{}' where id='f1400000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1400000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.platform_accept_manager_invitation(current_setting('test.reissued')::uuid)$$,'P0001','INVITATION_REVOKED','revoked operator cannot authorize pending grant');
select ok(not has_table_privilege('authenticated','public.workspaces','INSERT,DELETE'),'clients cannot provision or delete workspaces directly');
select * from finish();rollback;
